CREATE view [dbo].[HEAD_LST_KBK] as SELECT        TOP (100) PERCENT NUMBER, TAG AS htag, TAG - 2 AS dtag, ANBAR, NUMBER1, DATE_N, TAH, MAS, VAS, N_S, CUST_NO, MOLAH, M_NAGHD, MABL_VAR, MOIN_VAR, MABL_HAV, MOIN_HAV, MABL_HAZ, MOIN_HAZ, TAKHFIF, MOIN_KHF, ANBARF, FNUMCO, USER_NAME, DEPATMAN, SHIFT, CUST_KIND, MBAA,  HMBAA , OKF, SGN1, SGN2, SGN3, SGN4, SGN1usid, sgn2usid, sgn3usid,UID FROM dbo.HEAD_LST WHERE (TAG = 3) ORDER BY NUMBER1
